def valid(number):
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")
    if len(digits) < 2 or any(c < "0" or c > "9" for c in digits):
        return False

    total = 0
    for i, c in enumerate(reversed(digits)):
        digit = int(c)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
